import {esc} from './organiser-utils.js';
export async function calendarConnection(host,sb,team,admin,isCurrent=()=>true){
 const r=await sb.rpc('elan_calendar_status');if(!isCurrent())return;
 if(r.error){host.textContent='Calendar sync is unavailable. Bookings can still be recorded manually.';return;}
 const c=r.data?.connection;const issues=r.data?.issues||[];const stale=c?.last_sync&&Date.now()-Date.parse(c.last_sync)>20*60000;const label=stale?'Sync needs attention':c?.last_sync?'Connected':c?'Awaiting first sync':'Not connected';
 host.innerHTML='<div class="calendar-alert"><strong>Calendar · '+label+'</strong><p>'+esc(c?.last_sync?'Last successful contact: '+new Date(c.last_sync).toLocaleString():'Automatic booking sync is not active yet.')+'</p>'+(stale?'<p>No contact for over 20 minutes. Ask the calendar owner to check Apps Script executions and the five-minute trigger.</p>':'')+(issues.length?'<p>'+issues.length+' booking issue(s) need review. Open connection details below for the reason and next step.</p>':'')+'<button type="button" data-refresh-calendar>Refresh sync status</button></div><details class="readiness-paper"><summary>Interview Calendar connection · '+label+'</summary><p>Bookings are matched by application email. Sync runs approximately every five minutes after the calendar owner activates it. Reschedule requests in Élan do not change Google Calendar.</p><p>'+esc(c?'Calendar: '+c.calendar+' · '+(c.last_sync?'Last contact: '+new Date(c.last_sync).toLocaleString():'Setup has not contacted Élan yet.'):'Manual booking controls remain available.')+'</p>'+(r.data?.issues||[]).map(x=>'<p class="applicant-message"><strong>'+esc(x.applicant||'Unmatched Calendar booking')+'</strong>'+(x.enquiry_id?' <button type="button" data-calendar-app="'+esc(x.enquiry_id)+'">Open application</button>':'')+'<br>'+esc(x.note)+'<br>'+esc(x.note?.includes('Another active')||x.note?.includes('manually recorded')?'Compare the bookings with the applicant before cancelling or replacing a slot.':(/timed slot|start and end|duration|meeting link|joining link/i.test(x.note||''))?'Check the event’s start/end time, duration and meeting link. Save it in Calendar. With the updated sync script, it will be rechecked automatically.':'Review the event in Calendar and the application in Élan. After correcting the issue, the updated sync script will recheck it automatically.')+'</p>').join('')+(admin?'<form data-calendar><label>Calendar ID<input name="calendar" value="'+esc(c?.calendar||'the.elan.summit@gmail.com')+'" maxlength="250" required></label><p>Use the ID of the calendar receiving bookings; it may differ from the account email.</p><label>Exact beginning of interview event title<input name="title" value="'+esc(c?.title||'')+'" minlength="5" maxlength="150" required></label><fieldset><legend>Interviewers assigned to these slots</legend>'+team.map(t=>'<label class="check-row"><input type="checkbox" name="interviewer" value="'+esc(t.id)+'">'+esc(t.label)+'</label>').join('')+'</fieldset><p>Choose the people who actually attend every slot. Saving replaces the existing connection key; update Script Properties if you reconnect.</p><button>Prepare Calendar connection</button><p role="status"></p></form><div data-setup></div>'+(c?'<button type="button" data-disconnect>Disconnect Calendar sync</button>':''):'<p>The administrator can configure or disconnect this connection.</p>')+'</details>';
 host.querySelector('[data-refresh-calendar]').onclick=()=>{if(host.querySelector('[data-calendar][data-dirty=true]')&&!confirm('Discard unsaved Calendar connection settings?'))return;if(host.querySelector('[data-setup] textarea')){if(!confirm('Refresh and hide the connection key? Save it in Script Properties first.'))return;}calendarConnection(host,sb,team,admin,isCurrent);};
 const f=host.querySelector('form');if(f)f.oninput=()=>f.dataset.dirty='true';if(f)f.onsubmit=async e=>{e.preventDefault();if(f.inert||!f.reportValidity())return;const ids=[...f.querySelectorAll(':checked')].map(x=>x.value),note=f.querySelector('[role=status]');if(!ids.length){note.textContent='Choose at least one interviewer.';return;}f.inert=true;try{const res=await sb.rpc('elan_calendar_configure',{p_calendar:f.elements.calendar.value.trim(),p_title:f.elements.title.value.trim(),p_interviewers:ids});if(res.error)throw res.error;note.textContent='Connection prepared. Complete setup in the calendar owner’s Google account.';const out=host.querySelector('[data-setup]');out.innerHTML='<h3>One-time Google setup</h3><p>Sign into the.elan.summit@gmail.com and open <a href="https://script.google.com/home/start" target="_blank" rel="noopener">Google Apps Script</a>. Create a project, copy these files, enable the Calendar advanced service and add the Script Properties below. Run setupElanCalendar and authorise the requested access.</p><p><a href="/assets/calendar-setup/Code.gs" download>Download Code.gs</a> · <a href="/assets/calendar-setup/appsscript.json" download>Download manifest</a> · <a href="/assets/calendar-setup/SETUP.md" download>Full setup instructions</a></p><p>The connection key is shown only here. Keep it in Script Properties; do not paste it into the website repository or share it.</p><label>Script Properties<textarea readonly rows="5"></textarea></label>';out.querySelector('textarea').value='ELAN_CALENDAR = '+res.data.calendar+'\nELAN_TITLE = '+res.data.title+'\nELAN_TOKEN = '+res.data.token;}catch(err){note.textContent=err.message;}finally{f.inert=false;}};
 const b=host.querySelector('[data-disconnect]');if(b)b.onclick=async()=>{if(!confirm('Stop importing Calendar bookings? Existing interview records will remain.'))return;b.disabled=true;const res=await sb.rpc('elan_calendar_disable');if(res.error){b.disabled=false;b.textContent=res.error.message;}else await calendarConnection(host,sb,team,admin,isCurrent);};
}
